package com.bank.portfolio.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "holdings")
public class Holding {
    @Id @Column(name = "holding_id") private String holdingId;
    @Column(name = "account_id") private String accountId;
    private String symbol;
    private int quantity;
    @Column(name = "buy_price") private BigDecimal buyPrice;
    @Column(name = "current_price") private BigDecimal currentPrice;
    private String status;

    protected Holding() {}

    public BigDecimal getMarketValue() {
        return currentPrice.multiply(BigDecimal.valueOf(quantity));
    }

    public BigDecimal getInvestedValue() {
        return buyPrice.multiply(BigDecimal.valueOf(quantity));
    }

    public BigDecimal getProfitLoss() {
        return getMarketValue().subtract(getInvestedValue());
    }

    public boolean isActive() { return "ACTIVE".equals(status); }
    public boolean isProfitable() { return getProfitLoss().signum() > 0; }

    public String getHoldingId() { return holdingId; }
    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public int getQuantity() { return quantity; }
    public BigDecimal getBuyPrice() { return buyPrice; }
    public BigDecimal getCurrentPrice() { return currentPrice; }
    public String getStatus() { return status; }
}
