// DEMONSTRATES ALL FOUR CORE FUNCTIONAL INTERFACES IN ONE PIPELINE
package com.bank.portfolio.service;

import com.bank.portfolio.dto.PortfolioReport;
import com.bank.portfolio.dto.PortfolioReport.HoldingDetail;
import com.bank.portfolio.model.Holding;
import com.bank.portfolio.repository.HoldingRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.UUID;
import java.util.function.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class PortfolioAnalysisService {

    private final HoldingRepository holdingRepo;

    // ═══════════════════════════════════════════════════
    // DEFINE EACH FUNCTIONAL INTERFACE AS A NAMED FIELD
    // ═══════════════════════════════════════════════════

    // ── SUPPLIER<T>: nothing → T (factory / generator) ──
    private final Supplier<String> reportIdGenerator =
        () -> "RPT-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

    // ── PREDICATE<T>: T → boolean (filter / condition) ──
    private final Predicate<Holding> isActive = Holding::isActive;
    private final Predicate<Holding> isProfitable = Holding::isProfitable;
    private final Predicate<Holding> isActiveProfitable = isActive.and(isProfitable); // composed!

    // ── FUNCTION<T,R>: T → R (transformation) ──
    private final Function<Holding, BigDecimal> toMarketValue = Holding::getMarketValue;
    private final Function<Holding, BigDecimal> toProfitLoss = Holding::getProfitLoss;
    private final Function<Holding, HoldingDetail> toDetail = h -> new HoldingDetail(
        h.getSymbol(), h.getQuantity(), h.getMarketValue(),
        h.getProfitLoss(), h.isProfitable() ? "PROFIT" : "LOSS");

    // ── CONSUMER<T>: T → void (side effect / action) ──
    private final Consumer<Holding> logHolding = h ->
        log.info("   {} | Qty: {} | Market: Rs.{} | P/L: Rs.{}",
            h.getSymbol(), h.getQuantity(), h.getMarketValue(),
            h.getProfitLoss());
    private final Consumer<Holding> alertIfLoss = h -> {
        if (!h.isProfitable()) {
            log.warn("  (Caution) LOSS ALERT: {} down Rs.{}", h.getSymbol(), h.getProfitLoss().abs());
        }
    };
    private final Consumer<Holding> fullLogging = logHolding.andThen(alertIfLoss); // composed!

    // ── UNARY OPERATOR<T>: T → T (same-type transform) ──
    private final UnaryOperator<BigDecimal> roundToPaisa =
        amount -> amount.setScale(2, RoundingMode.HALF_UP);

    // ── BINARY OPERATOR<T>: (T,T) → T (reduction) ──
    private final BinaryOperator<BigDecimal> sum = BigDecimal::add;

    @Transactional(readOnly = true)
    public PortfolioReport analyzePortfolio(String accountId) {
        List<Holding> allHoldings = holdingRepo.findByAccountId(accountId);

        // ── SUPPLIER: generate report ID ──
        String reportId = reportIdGenerator.get();
        log.info("═══ Portfolio Analysis {} for account {} ═══", reportId, accountId);

        // ── PREDICATE: filter active holdings ──
        List<Holding> activeHoldings = allHoldings.stream()
            .filter(isActive)                    // Predicate<Holding>
            .toList();

        // ── CONSUMER: log each holding ──
        activeHoldings.forEach(fullLogging);     // Consumer<Holding> (composed: log + alert)

        // ── FUNCTION: transform to DTOs ──
        List<HoldingDetail> details = activeHoldings.stream()
            .map(toDetail)                       // Function<Holding, HoldingDetail>
            .toList();

        // ── FUNCTION + BINARY OPERATOR: calculate totals ──
        BigDecimal totalInvested = activeHoldings.stream()
            .map(Holding::getInvestedValue)      // Function<Holding, BigDecimal>
            .reduce(BigDecimal.ZERO, sum);        // BinaryOperator<BigDecimal>

        BigDecimal totalMarketValue = activeHoldings.stream()
            .map(toMarketValue)                  // Function<Holding, BigDecimal>
            .reduce(BigDecimal.ZERO, sum);        // BinaryOperator<BigDecimal>

        // ── UNARY OPERATOR: round to paisa ──
        BigDecimal totalPL = roundToPaisa.apply(totalMarketValue.subtract(totalInvested));

        // ── PREDICATE: determine profit status ──
        String profitStatus = totalPL.signum() > 0 ? " PROFIT" : " LOSS";

        log.info("═══ Total: Invested Rs.{} | Market Rs.{} | P/L Rs.{} {} ═══",
            totalInvested, totalMarketValue, totalPL, profitStatus);

        return new PortfolioReport(
            reportId, accountId, activeHoldings.size(),
            roundToPaisa.apply(totalInvested),
            roundToPaisa.apply(totalMarketValue),
            totalPL, profitStatus, details,
            "Supplier(reportId) → Predicate(filter) → Consumer(log) → Function(map) → BinaryOperator(reduce)"
        );
    }

    // ── BIFUNCTION + BIPREDICATE demo ──
    @Transactional(readOnly = true)
    public List<HoldingDetail> filterByMinValue(String accountId, BigDecimal minValue) {
        // BiPredicate<Holding, BigDecimal>: two inputs → boolean
        BiPredicate<Holding, BigDecimal> exceedsMinValue =
            (holding, min) -> holding.getMarketValue().compareTo(min) > 0;

        // BiFunction<Holding, BigDecimal, HoldingDetail>: two inputs → one output
        BiFunction<Holding, BigDecimal, String> describeVsMin =
            (holding, min) -> holding.getSymbol() + " value Rs." + holding.getMarketValue()
                + " exceeds minimum Rs." + min;

        return holdingRepo.findByAccountId(accountId).stream()
            .filter(isActive)
            .filter(h -> exceedsMinValue.test(h, minValue))  // BiPredicate
            .peek(h -> log.info(describeVsMin.apply(h, minValue)))  // BiFunction for logging
            .map(toDetail)
            .toList();
    }
}
