package com.bank.portfolio.service;

import com.bank.portfolio.model.Holding;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.function.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class FunctionalInterfacePipelineTest {

    // ═══ PREDICATE: T → boolean ═══
    @Test
    void predicateFiltersCorrectly() {
        Predicate<Holding> isActive = Holding::isActive;
        Predicate<Holding> isProfitable = Holding::isProfitable;
        Predicate<Holding> both = isActive.and(isProfitable);

        Holding active = mockHolding(true, true);
        Holding inactive = mockHolding(false, true);
        Holding losing = mockHolding(true, false);

        assertThat(both.test(active)).isTrue();
        assertThat(both.test(inactive)).isFalse();
        assertThat(both.test(losing)).isFalse();
    }

    @Test
    void predicateNegation() {
        Predicate<String> isBlank = String::isBlank;
        Predicate<String> notBlank = isBlank.negate();
        Predicate<String> notBlankStatic = Predicate.not(String::isBlank);

        assertThat(notBlank.test("RELIANCE")).isTrue();
        assertThat(notBlankStatic.test("")).isFalse();
    }

    // ═══ FUNCTION: T → R ═══
    @Test
    void functionTransforms() {
        Function<Holding, BigDecimal> toMarketValue = Holding::getMarketValue;
        Function<BigDecimal, String> format = amt -> "Rs." + amt;

        // andThen: Holding → BigDecimal → String
        Function<Holding, String> formatted = toMarketValue.andThen(format);

        Holding h = mock(Holding.class);
        when(h.getMarketValue()).thenReturn(new BigDecimal("245050"));
        assertThat(formatted.apply(h)).isEqualTo("Rs.245050");
    }

    @Test
    void functionIdentity() {
        Function<String, String> identity = Function.identity();
        assertThat(identity.apply("RELIANCE")).isEqualTo("RELIANCE");
    }

    // ═══ CONSUMER: T → void ═══
    @Test
    void consumerChains() {
        StringBuilder log = new StringBuilder();
        Consumer<String> first = s -> log.append("[LOG:").append(s).append("]");
        Consumer<String> second = s -> log.append("[AUDIT:").append(s).append("]");

        Consumer<String> both = first.andThen(second);
        both.accept("TRD-001");

        assertThat(log.toString()).isEqualTo("[LOG:TRD-001][AUDIT:TRD-001]");
    }

    // ═══ SUPPLIER: () → T ═══
    @Test
    void supplierProducesLazily() {
        Supplier<String> idGen = () -> "RPT-" + System.nanoTime();

        String id1 = idGen.get();
        String id2 = idGen.get();
        assertThat(id1).isNotEqualTo(id2);  // each call produces new value
        assertThat(id1).startsWith("RPT-");
    }

    // ═══ BINARY OPERATOR: (T,T) → T ═══
    @Test
    void binaryOperatorReduces() {
        BinaryOperator<BigDecimal> sum = BigDecimal::add;
        BigDecimal result = sum.apply(new BigDecimal("100"), new BigDecimal("200"));
        assertThat(result).isEqualByComparingTo("300");
    }

    // ═══ UNARY OPERATOR: T → T ═══
    @Test
    void unaryOperatorTransformsSameType() {
        UnaryOperator<BigDecimal> addGST = amount -> amount.multiply(new BigDecimal("1.18"));
        BigDecimal result = addGST.apply(new BigDecimal("1000"));
        assertThat(result).isEqualByComparingTo("1180");
    }

    private Holding mockHolding(boolean active, boolean profitable) {
        Holding h = mock(Holding.class);
        when(h.isActive()).thenReturn(active);
        when(h.isProfitable()).thenReturn(profitable);
        return h;
    }
}
